index 74c0561..e3c7bd9 100644
--- a/src/server.mjs
+++ b/src/server.mjs
@@ -1,6 +1,189 @@
-// Prepared transport only. No product implementation exists at the baseline.
 import http from 'node:http';
-http.createServer((req, res) => {
-  res.writeHead(req.url === '/api/health' ? 200 : 501, {'content-type':'application/json'});
-  res.end(JSON.stringify(req.url === '/api/health' ? {ok:true} : {error:'Not implemented'}));
-}).listen(Number(process.env.PORT || 4380), process.env.HOST || '127.0.0.1');
+import { isIP } from 'node:net';
+import { resolve } from 'node:path';
+import { pathToFileURL } from 'node:url';
+import { HttpError } from './errors.mjs';
+import { InventoryStore } from './store.mjs';
+
+export const maxBodyBytes = 2 * 1024 * 1024;
+
+function json(res, status, value, headers = {}) {
+  const body = JSON.stringify(value);
+  res.writeHead(status, {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Content-Length': Buffer.byteLength(body),
+    'Cache-Control': 'no-store',
+    'X-Content-Type-Options': 'nosniff',
+    ...headers,
+  });
+  res.end(body);
+}
+
+function allowMethod(req, allowed) {
+  if (!allowed.includes(req.method)) {
+    throw new HttpError(405, 'Metodo HTTP non consentito.', { Allow: allowed.join(', ') });
+  }
+}
+
+async function readBody(req) {
+  return new Promise((resolveBody, reject) => {
+    let size = 0;
+    let chunks = [];
+    let failed = false;
+    const fail = error => {
+      if (failed) return;
+      failed = true;
+      chunks = [];
+      reject(error);
+    };
+    req.on('data', chunk => {
+      // Continue draining rejected requests without retaining their contents.
+      // Destroying the request here could also destroy the JSON error response.
+      if (failed) return;
+      size += chunk.length;
+      if (size > maxBodyBytes) {
+        fail(new HttpError(413, 'Il corpo HTTP supera il limite di 2 MiB.', { Connection: 'close' }));
+      } else {
+        chunks.push(chunk);
+      }
+    });
+    req.once('aborted', () => fail(new HttpError(400, 'Richiesta interrotta.')));
+    req.once('error', () => fail(new HttpError(400, 'Impossibile leggere il corpo della richiesta.')));
+    req.once('end', () => {
+      if (failed) return;
+      resolveBody(Buffer.concat(chunks, size));
+    });
+    if (Number(req.headers['content-length']) > maxBodyBytes) {
+      fail(new HttpError(413, 'Il corpo HTTP supera il limite di 2 MiB.', { Connection: 'close' }));
+    }
+  });
+}
+
+function parseJson(req, body) {
+  const contentType = req.headers['content-type'];
+  if (contentType && contentType.split(';', 1)[0].trim().toLowerCase() !== 'application/json') {
+    throw new HttpError(415, 'Il corpo deve usare Content-Type: application/json.');
+  }
+  if (req.headers['content-encoding'] && req.headers['content-encoding'].toLowerCase() !== 'identity') {
+    throw new HttpError(415, 'La compressione del corpo non è supportata.');
+  }
+  try {
+    const text = new TextDecoder('utf-8', { fatal: true }).decode(body);
+    return JSON.parse(text);
+  } catch {
+    throw new HttpError(400, 'Il corpo deve contenere JSON valido in UTF-8.');
+  }
+}
+
+export function createRequestHandler(store) {
+  return async (req, res) => {
+    try {
+      let pathname;
+      let searchParams;
+      try {
+        const url = new URL(req.url, 'http://localhost');
+        pathname = decodeURIComponent(url.pathname);
+        searchParams = url.searchParams;
+      } catch {
+        throw new HttpError(400, 'Indirizzo della richiesta non valido.');
+      }
+      const body = await readBody(req);
+
+      if (pathname === '/api/health') {
+        allowMethod(req, ['GET']);
+        json(res, 200, { ok: true });
+      } else if (pathname === '/api/items') {
+        allowMethod(req, ['GET', 'POST']);
+        if (req.method === 'GET') {
+          const filters = Object.fromEntries(['q', 'category', 'location'].map(key =>
+            [key, searchParams.get(key) ?? '']));
+          json(res, 200, store.list(filters));
+        } else {
+          const item = store.create(parseJson(req, body));
+          json(res, 201, item, { Location: `/api/items/${encodeURIComponent(item.id)}` });
+        }
+      } else {
+        const match = /^\/api\/items\/([^/]+)$/.exec(pathname);
+        if (!match) throw new HttpError(404, 'Risorsa non trovata.');
+        allowMethod(req, ['PATCH', 'DELETE']);
+        if (req.method === 'PATCH') {
+          json(res, 200, store.patch(match[1], parseJson(req, body)));
+        } else {
+          if (body.length !== 0) throw new HttpError(400, 'L’eliminazione non accetta un corpo HTTP.');
+          store.delete(match[1]);
+          json(res, 200, { ok: true });
+        }
+      }
+    } catch (error) {
+      if (req.aborted || res.destroyed) return;
+      if (error instanceof HttpError) {
+        json(res, error.status, { error: error.message }, error.headers);
+      } else {
+        console.error('Errore durante l’operazione sull’archivio:', error);
+        json(res, 500, { error: 'Impossibile completare l’operazione sull’archivio.' });
+      }
+    } finally {
+      req.resume();
+    }
+  };
+}
+
+function listenOptions(environment) {
+  let host = environment.HOST || '127.0.0.1';
+  if (host === 'localhost') host = '127.0.0.1';
+  if (host !== '::1' && !(isIP(host) === 4 && host.startsWith('127.'))) {
+    throw new Error('HOST deve essere un indirizzo loopback (127.0.0.1, ::1 o localhost).');
+  }
+  const rawPort = environment.PORT || '4380';
+  if (!/^\d+$/.test(rawPort) || Number(rawPort) > 65535) {
+    throw new Error('PORT deve essere un intero tra 0 e 65535.');
+  }
+  return { host, port: Number(rawPort) };
+}
+
+export function startServer(environment = process.env) {
+  const options = listenOptions(environment);
+  const store = new InventoryStore(environment.CUSTODE_DATA_DIR);
+  const server = http.createServer({ maxHeaderSize: 16 * 1024 }, createRequestHandler(store));
+  server.requestTimeout = 30_000;
+  server.headersTimeout = 10_000;
+  server.keepAliveTimeout = 5_000;
+
+  let stopping = false;
+  const shutdown = () => {
+    if (stopping) return;
+    stopping = true;
+    server.close();
+    const timeout = setTimeout(() => server.closeAllConnections(), 5000);
+    timeout.unref();
+    server.once('close', () => clearTimeout(timeout));
+  };
+  process.once('SIGINT', shutdown);
+  process.once('SIGTERM', shutdown);
+  server.once('close', () => {
+    process.removeListener('SIGINT', shutdown);
+    process.removeListener('SIGTERM', shutdown);
+    store.close();
+  });
+  server.once('error', error => {
+    console.error('Impossibile avviare il server Custode:', error.message);
+    process.exitCode = 1;
+    shutdown();
+  });
+  server.listen(options, () => {
+    const address = server.address();
+    const host = options.host.includes(':') ? `[${options.host}]` : options.host;
+    console.log(`Custode: http://${host}:${address.port}`);
+    console.log(`Archivio: ${store.path}`);
+  });
+  return server;
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
+  try {
+    startServer();
+  } catch (error) {
+    console.error('Impossibile avviare Custode:', error.message);
+    process.exitCode = 1;
+  }
+}
