+++ b/src/store.mjs
+import { randomUUID } from 'node:crypto';
+import { lstatSync, mkdirSync, realpathSync } from 'node:fs';
+import { homedir } from 'node:os';
+import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
+import { DatabaseSync } from 'node:sqlite';
+import { fileURLToPath } from 'node:url';
+import { HttpError } from './errors.mjs';
+import { filterItems, validateItemFields } from './inventory.mjs';
+
+const projectDirectory = realpathSync(fileURLToPath(new URL('..', import.meta.url)));
+export const defaultDataDirectory = join(homedir(), '.local', 'share', 'custode');
+const columns = 'id, name, category, location, notes, createdAt, updatedAt';
+const textFields = ['name', 'category', 'location', 'notes'];
+
+function storedText(item) {
+  // Encode each string as JSON: the native SQLite text interface truncates
+  // reads at embedded NULs and replaces isolated UTF-16 surrogates. JSON
+  // escapes those values while keeping the HTTP round-trip lossless.
+  return textFields.map(key => JSON.stringify(item[key]));
+}
+
+function readItem(row) {
+  if (!row) return undefined;
+  const item = { ...row };
+  for (const key of textFields) item[key] = JSON.parse(row[key]);
+  return item;
+}
+
+function within(parent, child) {
+  const path = relative(parent, child);
+  return path === '' || (!isAbsolute(path) && path !== '..' && !path.startsWith(`..${sep}`));
+}
+
+function prepareDataDirectory(directory) {
+  const requested = resolve(directory || defaultDataDirectory);
+  // Resolve existing ancestors too, so a symlink cannot redirect storage into
+  // the source tree. Do this before creating any directory.
+  let ancestor = requested;
+  let canonical;
+  while (canonical === undefined) {
+    try {
+      canonical = resolve(realpathSync(ancestor), relative(ancestor, requested));
+    } catch (error) {
+      if (error.code !== 'ENOENT' || dirname(ancestor) === ancestor) throw error;
+      ancestor = dirname(ancestor);
+    }
+  }
+  if (within(projectDirectory, requested) || within(projectDirectory, canonical)) {
+    throw new Error('CUSTODE_DATA_DIR deve trovarsi fuori dal repository.');
+  }
+  mkdirSync(canonical, { recursive: true, mode: 0o700 });
+  return canonical;
+}
+
+export class InventoryStore {
+  constructor(directory) {
+    this.directory = prepareDataDirectory(directory);
+    this.path = join(this.directory, 'custode.sqlite');
+    try {
+      if (lstatSync(this.path).isSymbolicLink()) {
+        throw new Error('Il file di archivio non può essere un collegamento simbolico.');
+      }
+    } catch (error) {
+      if (error.code !== 'ENOENT') throw error;
+    }
+
+    this.database = new DatabaseSync(this.path);
+    try {
+      this.database.exec('PRAGMA busy_timeout = 5000; PRAGMA foreign_keys = ON;');
+      const version = this.database.prepare('PRAGMA user_version').get().user_version;
+      if (version !== 0 && version !== 1) {
+        throw new Error(`Versione archivio non supportata: ${version}.`);
+      }
+      if (version === 0 && this.database.prepare(
+        "SELECT name FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' LIMIT 1"
+      ).get()) {
+        throw new Error('Archivio non riconosciuto: nessun dato è stato sostituito.');
+      }
+      const checks = this.database.prepare('PRAGMA quick_check').all();
+      if (checks.length !== 1 || checks[0].quick_check !== 'ok') {
+        throw new Error('Archivio danneggiato: verificare i dati prima di riavviare.');
+      }
+      this.database.exec('PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
+      if (version === 0) {
+        this.transaction(() => {
+          this.database.exec(`
+            CREATE TABLE items (
+              id TEXT PRIMARY KEY NOT NULL,
+              name TEXT NOT NULL,
+              category TEXT NOT NULL DEFAULT '',
+              location TEXT NOT NULL DEFAULT '',
+              notes TEXT NOT NULL DEFAULT '',
+              createdAt TEXT NOT NULL,
+              updatedAt TEXT NOT NULL
+            ) STRICT;
+            PRAGMA user_version = 1;
+          `);
+        });
+      }
+      this.selectAll = this.database.prepare(`SELECT ${columns} FROM items ORDER BY rowid`);
+      this.selectOne = this.database.prepare(`SELECT ${columns} FROM items WHERE id = ?`);
+      this.insert = this.database.prepare(`INSERT INTO items (${columns}) VALUES (?, ?, ?, ?, ?, ?, ?)`);
+      this.update = this.database.prepare(
+        'UPDATE items SET name = ?, category = ?, location = ?, notes = ?, updatedAt = ? WHERE id = ?'
+      );
+      this.remove = this.database.prepare('DELETE FROM items WHERE id = ?');
+    } catch (error) {
+      this.database.close();
+      throw error;
+    }
+  }
+
+  transaction(operation) {
+    this.database.exec('BEGIN IMMEDIATE');
+    try {
+      const result = operation();
+      this.database.exec('COMMIT');
+      return result;
+    } catch (error) {
+      try {
+        this.database.exec('ROLLBACK');
+      } catch (rollbackError) {
+        // Keep the original error and make an unsuccessful rollback visible.
+        console.error('Errore durante il rollback dell’archivio:', rollbackError);
+      }
+      throw error;
+    }
+  }
+
+  list(filters) {
+    return filterItems(this.selectAll.all().map(readItem), filters);
+  }
+
+  create(input) {
+    const fields = validateItemFields(input);
+    return this.transaction(() => {
+      const id = randomUUID();
+      const timestamp = new Date().toISOString();
+      this.insert.run(id, ...storedText(fields), timestamp, timestamp);
+      return readItem(this.selectOne.get(id));
+    });
+  }
+
+  patch(id, input) {
+    const fields = validateItemFields(input, { partial: true });
+    return this.transaction(() => {
+      const current = readItem(this.selectOne.get(id));
+      if (!current) throw new HttpError(404, 'Oggetto non trovato.');
+      const changed = { ...current, ...fields };
+      // Keep update times monotonic even for consecutive writes in one
+      // millisecond or when the system clock moves backwards.
+      const updatedAt = new Date(Math.max(Date.now(), Date.parse(current.updatedAt) + 1)).toISOString();
+      this.update.run(...storedText(changed), updatedAt, id);
+      return readItem(this.selectOne.get(id));
+    });
+  }
+
+  delete(id) {
+    this.transaction(() => {
+      if (this.remove.run(id).changes === 0) throw new HttpError(404, 'Oggetto non trovato.');
+    });
+  }
+
+  close() {
+    this.database.close();
+  }
+}
+

