+        this.database.exec('ROLLBACK');
+      } catch (rollbackError) {
+        // Keep the original error and make an unsuccessful rollback visible.
+        console.error('Errore durante il rollback dell’archivio:', rollbackError);
+      }
+      throw error;
+    }
+  }
+
+  list(filters) {
+    return filterItems(this.selectAll.all().map(readItem), filters);
+  }
+
+  create(input) {
+    const fields = validateItemFields(input);
+    return this.transaction(() => {
+      const id = randomUUID();
+      const timestamp = new Date().toISOString();
+      this.insert.run(id, ...storedText(fields), timestamp, timestamp);
+      return readItem(this.selectOne.get(id));
+    });
+  }
+
+  patch(id, input) {
+    const fields = validateItemFields(input, { partial: true });
+    return this.transaction(() => {
+      const current = readItem(this.selectOne.get(id));
+      if (!current) throw new HttpError(404, 'Oggetto non trovato.');
+      const changed = { ...current, ...fields };
+      // Keep update times monotonic even for consecutive writes in one
+      // millisecond or when the system clock moves backwards.
+      const updatedAt = new Date(Math.max(Date.now(), Date.parse(current.updatedAt) + 1)).toISOString();
+      this.update.run(...storedText(changed), updatedAt, id);
+      return readItem(this.selectOne.get(id));
+    });
+  }
+
+  delete(id) {
+    this.transaction(() => {
+      if (this.remove.run(id).changes === 0) throw new HttpError(404, 'Oggetto non trovato.');
+    });
+  }
+
+  close() {
+    this.database.close();
+  }
+}
+

