+const element = id => document.getElementById(id);
+const dialog = element('item-dialog');
+const form = element('item-form');
+const newItemButton = element('new-item');
+const saveButton = element('save-item');
+const searchInput = element('item-search');
+const fieldNames = ['name', 'category', 'location', 'notes'];
+const limits = { name: 200, category: 100, location: 100, notes: 5000 };
+let items = [];
+let loadedQuery = null;
+let loadSequence = 0;
+let loadController;
+let searchTimer;
+let saving = false;
+let formOpener = newItemButton;
+
+class ApiError extends Error {}
+
+async function requestJSON(url, options = {}) {
+  const response = await fetch(url, {
+    ...options,
+    headers: { Accept: 'application/json', ...options.headers },
+    cache: 'no-store',
+  });
+  let data;
+  try {
+    data = await response.json();
+  } catch {
+    throw new ApiError('Il servizio ha restituito una risposta inattesa.');
+  }
+  if (!response.ok) {
+    throw new ApiError(typeof data?.error === 'string' ? data.error : 'Operazione non riuscita.');
+  }
+  return data;
+}
+
+function isItem(item) {
+  return item !== null && typeof item === 'object' &&
+    typeof item.id === 'string' && item.id.length > 0 &&
+    fieldNames.every(name => typeof item[name] === 'string');
+}
+
+function node(tag, className, text) {
+  const result = document.createElement(tag);
+  if (className) result.className = className;
+  if (text !== undefined) result.textContent = text;
+  return result;
+}
+
+function itemCard(item, index) {
+  const entry = node('li');
+  const card = node('article', 'item-card');
+  card.dataset.itemId = item.id;
+  const heading = node('div', 'card-heading');
+  const symbol = node('span', 'item-symbol');
+  symbol.setAttribute('aria-hidden', 'true');
+  // Clone a trusted local illustration; user content is always textContent.
+  symbol.append(document.querySelector('#inventory-tab svg').cloneNode(true));
+  const title = node('h4', '', item.name);
+  title.id = `item-title-${index}`;
+  card.setAttribute('aria-labelledby', title.id);
+  heading.append(symbol, title);
+  const details = node('dl', 'item-details');
+  for (const [field, label] of [['category', 'Categoria'], ['location', 'Posizione']]) {
+    const detail = node('div');
+    const value = node('dd', item[field].trim() ? '' : 'unspecified', item[field].trim() ? item[field] : 'Non indicata');
+    detail.append(node('dt', '', label), value);
+    details.append(detail);
+  }
+  card.append(heading, details);
+  if (item.notes) {
+    const notes = node('div', 'item-notes');
+    notes.append(node('p', 'item-notes-label', 'Note'), node('p', 'item-notes-text', item.notes));
+    card.append(notes);
+  }
+  entry.append(card);
+  return entry;
+}
+
+function itemCount(query) {
+  const count = items.length;
+  return query
+    ? `${count} ${count === 1 ? 'risultato' : 'risultati'}`
+    : `${count} ${count === 1 ? 'oggetto' : 'oggetti'}`;
+}
+
+function renderItems(query) {
+  const count = items.length;
+  element('items-summary').textContent = itemCount(query);
+  // A filtered result count is not the size of the household inventory.
+  if (!query) element('nav-count').textContent = String(count);
+  element('item-list').replaceChildren(...items.map(itemCard));
+  element('item-list').hidden = count === 0;
+  element('empty-state').hidden = Boolean(query) || count !== 0;
+  element('no-results-state').hidden = !query || count !== 0;
+  element('no-results-query').textContent = `«${query}»`;
+}
+
+function invalidateListLoad() {
+  // Invalidate immediately on input, including during the debounce interval.
+  // Aborting alone is insufficient if an older response has already arrived.
+  loadSequence += 1;
+  clearTimeout(searchTimer);
+  loadController?.abort();
+  loadController = undefined;
+  return loadSequence;
+}
+
+function showListLoading(query) {
+  element('inventory-results').setAttribute('aria-busy', 'true');
+  element('clear-search').hidden = !query;
+  element('nav-count').hidden = Boolean(query);
+  if (!query) element('nav-count').textContent = '–';
+  element('list-error').hidden = true;
+  element('retry-items').disabled = true;
+  element('refresh-items').disabled = true;
+  element('loading-state').textContent = query ? 'Ricerca degli oggetti…' : 'Caricamento dell’inventario…';
+  element('loading-state').hidden = false;
+  element('empty-state').hidden = true;
+  element('no-results-state').hidden = true;
+  element('item-list').hidden = true;
+  element('items-summary').textContent = query ? 'Ricerca in corso…' : 'Caricamento…';
+}
+
+async function loadItems() {
+  const query = searchInput.value;
+  const sequence = invalidateListLoad();
+  const controller = new AbortController();
+  let timedOut = false;
+  const timeout = setTimeout(() => {
+    timedOut = true;
+    controller.abort();
+  }, 10000);
+  loadController = controller;
+  showListLoading(query);
+  try {
+    const params = new URLSearchParams({ q: query });
+    const result = await requestJSON(query ? `/api/items?${params}` : '/api/items', { signal: controller.signal });
+    if (sequence !== loadSequence) return;
+    if (!Array.isArray(result) || !result.every(isItem)) {
+      throw new ApiError('Il servizio ha restituito un elenco non valido.');
+    }
+    items = result;
+    loadedQuery = query;
+    renderItems(query);
+  } catch (error) {
+    if (sequence !== loadSequence) return;
+    const message = timedOut
+      ? 'Il servizio non ha risposto in tempo. Controlla che Custode sia in esecuzione e riprova.'
+      : error instanceof ApiError ? error.message : 'Controlla che Custode sia in esecuzione e riprova.';
+    // Keep previous cards only when they belong to this exact query. In
+    // particular, a failed search must not present the whole archive as hits.
+    const showPrevious = loadedQuery === query && items.length > 0;
+    element('item-list').hidden = !showPrevious;
+    element('list-error-title').textContent = query ? 'Ricerca non disponibile' : 'Inventario non disponibile';
+    element('list-error-message').textContent = (showPrevious
+      ? 'Stai vedendo l’ultimo elenco caricato, che potrebbe non essere aggiornato. '
+      : '') + `${message} Puoi riprovare o aggiungere un oggetto con Nuovo oggetto.`;
+    element('list-error').hidden = false;
+    element('items-summary').textContent = showPrevious
+      ? `${itemCount(query)} · da aggiornare`
+      : query ? 'Ricerca non disponibile' : 'Elenco non disponibile';
+  } finally {
+    clearTimeout(timeout);
+    if (sequence === loadSequence) {
+      loadController = undefined;
+      element('inventory-results').setAttribute('aria-busy', 'false');
+      element('loading-state').hidden = true;
+      element('retry-items').disabled = false;
+      element('refresh-items').disabled = false;
+    }
+  }
+}
+
+function searchChanged(event) {
+  invalidateListLoad();
+  showListLoading(searchInput.value);
+  // Wait for a complete input when a keyboard uses composition (IME).
+  if (event.isComposing) return;
+  if (!searchInput.value) void loadItems();
+  else searchTimer = setTimeout(loadItems, 200);
+}
+
+function clearSearch() {
+  searchInput.value = '';
+  searchInput.focus();
+  void loadItems();
+}
+
+function clearFieldError(name) {
+  form.elements.namedItem(name).removeAttribute('aria-invalid');
+  element(`${name}-error`).hidden = true;
+  element(`${name}-error`).textContent = '';
+}
+
+function clearFormErrors() {
+  element('form-error').hidden = true;
+  element('form-error').textContent = '';
+  for (const name of fieldNames) clearFieldError(name);
+}
+
+function openForm(event) {
+  formOpener = event.currentTarget;
+  clearFormErrors();
+  element('feedback').textContent = '';
+  dialog.showModal();
+  form.elements.namedItem('name').focus();
+}
+
+function closeForm() {
+  if (saving) return;
+  dialog.close();
+}
+
+function validateForm() {
+  let firstInvalid;
+  for (const name of fieldNames) {
+    const input = form.elements.namedItem(name);
+    let message = '';
+    if (name === 'name' && input.value.trim().length === 0) message = 'Inserisci il nome dell’oggetto.';
+    else if ([...input.value].length > limits[name]) message = `Usa al massimo ${limits[name]} caratteri.`;
+    if (message) {
+      input.setAttribute('aria-invalid', 'true');
+      element(`${name}-error`).textContent = message;
+      element(`${name}-error`).hidden = false;
+      firstInvalid ??= input;
+    }
+  }
+  firstInvalid?.focus();
+  return !firstInvalid;
+}
+
+function setSaving(value) {
+  saving = value;
+  element('item-fields').disabled = value;
+  element('cancel-form').disabled = value;
+  element('close-form').disabled = value;
+  saveButton.disabled = value;
+  saveButton.textContent = value ? 'Salvataggio…' : 'Salva oggetto';
+  form.setAttribute('aria-busy', String(value));
+}
+
+newItemButton.addEventListener('click', openForm);
+element('first-item').addEventListener('click', openForm);
+element('inventory-tab').addEventListener('click', () => element('main-content').focus());
+element('retry-items').addEventListener('click', loadItems);
+element('refresh-items').addEventListener('click', loadItems);
+searchInput.addEventListener('input', searchChanged);
+searchInput.addEventListener('compositionend', searchChanged);
+element('search-form').addEventListener('submit', event => {
+  event.preventDefault();
+  void loadItems();
+});
+element('clear-search').addEventListener('click', clearSearch);
+element('show-all-items').addEventListener('click', clearSearch);
+element('cancel-form').addEventListener('click', closeForm);
+element('close-form').addEventListener('click', closeForm);
+dialog.addEventListener('cancel', event => {
+  if (saving) event.preventDefault();
+});
+dialog.addEventListener('close', () => {
+  // An empty-state opener can disappear after saving the first object.
+  const target = formOpener.getClientRects().length ? formOpener : newItemButton;
+  target.focus();
+});
+for (const name of fieldNames) {
+  form.elements.namedItem(name).addEventListener('input', () => clearFieldError(name));
+}
+
+form.addEventListener('submit', async event => {
+  event.preventDefault();
+  if (saving) return;
+  clearFormErrors();
+  if (!validateForm()) return;
+  const fields = Object.fromEntries(fieldNames.map(name => [name, form.elements.namedItem(name).value]));
+  setSaving(true);
+  try {
+    const item = await requestJSON('/api/items', {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify(fields),
+    });
+    if (!isItem(item)) throw new ApiError('Il servizio ha restituito una risposta inattesa. Verifica l’elenco prima di riprovare.');
+    form.reset();
+    dialog.close();
+    element('feedback').textContent = `Oggetto salvato: ${item.name}.` + (searchInput.value
+      ? ' La ricerca è ancora attiva. Cancella la ricerca per vedere tutti gli oggetti.'
+      : '');
+    // The POST is already confirmed. A later list failure has its own message
+    // and must never be presented as a failed save or invite a duplicate POST.
+    void loadItems();
+  } catch (error) {
+    element('form-error').textContent = error instanceof ApiError
+      ? `${error.message} I campi sono stati conservati.`
+      : 'Salvataggio non confermato: il servizio non risponde. I campi sono stati conservati. Verifica l’elenco prima di riprovare.';
+    element('form-error').hidden = false;
+  } finally {
+    setSaving(false);
+    if (!element('form-error').hidden) element('form-error').focus();
+  }
+});
+
+newItemButton.disabled = false;
+void loadItems();
+
