+  const item = deletionItem;
+  element('delete-error').hidden = true;
+  setDeleting(true);
+  try {
+    await requestJSON(`/api/items/${encodeURIComponent(item.id)}`, {
+      method: 'DELETE',
+      signal: AbortSignal.timeout(10000),
+    });
+    deleteDialog.close();
+    announceMutation(`Oggetto eliminato: ${item.name}.`);
+  } catch (error) {
+    element('delete-error').textContent = error.status === 409
+      ? `Eliminazione non consentita: ${error.message} L’oggetto resta nell’elenco.`
+      : error.status === 404
+      ? 'L’oggetto non è più disponibile sul server. Annulla e usa Aggiorna elenco per verificarne lo stato.'
+      : error instanceof ApiError
+      ? `${error.message} Nessun oggetto è stato rimosso dall’elenco. Annulla e aggiorna l’elenco prima di riprovare.`
+      : 'Eliminazione non confermata: il servizio non risponde. Annulla e usa Aggiorna elenco prima di riprovare.';
+    element('delete-error').hidden = false;
+  } finally {
+    setDeleting(false);
+    if (!element('delete-error').hidden) element('delete-error').focus();
+  }
+});
+
+newItemButton.disabled = false;
+void loadItems();
