+  .page-description { font-size: .84rem; margin-top: 10px; }
+  .page-header > .button { width: 100%; }
+  .eyebrow { font-size: .6rem; margin-bottom: 10px; }
+  .inventory { margin-top: 30px; }
+  .collection-header { padding-bottom: 14px; gap: 10px; }
+  .collection-tools { gap: 5px; }
+  .collection-header h3 { font-size: .88rem; }
