+  .error-notice { align-items: flex-start; flex-direction: column; }
+  .item-dialog { padding: 22px; }
+  .dialog-heading h2 { font-size: 1.75rem; }
+  .field-row { grid-template-columns: minmax(0, 1fr); gap: 0; }
